// Xion cosmetics: the cape set generated by build/make-capes.js (src/assets/capes).
// The game can't read files inside the launcher's app.asar, so the set is copied to <root>/cosmetics/capes
// before a launch, and the pick travels to Xion Client in xion-launcher.json.
const fs = require('fs')
const path = require('path')

const SRC = path.join(__dirname, '..', 'assets', 'capes')
// Xion+ players' own cape (one 256x128 PNG), kept outside the game folder so a new game root keeps it.
const CUSTOM_DIR = path.join(require('electron').app.getPath('appData'), '.xionlauncher', 'custom-capes')
const customFile = id => path.join(CUSTOM_DIR, id + '.png')

let cached = null
function catalog () {
  if (!cached) {
    try { cached = JSON.parse(fs.readFileSync(path.join(SRC, 'capes.json'), 'utf8')) } catch { cached = [] }
  }
  return cached
}

/** The player's uploaded cape as a catalog entry, or null. */
function custom (settings) {
  const id = settings.customCape
  return id && fs.existsSync(customFile(id)) ? { id, name: 'My Cape', cat: 'Custom', tier: 'pro', frames: 1 } : null
}

/** The cape set plus the player's own cape. */
const all = settings => { const c = custom(settings); return c ? [c, ...catalog()] : catalog() }

const byId = (id, settings) => (settings ? all(settings) : catalog()).find(c => c.id === id) || null

/** Saves an uploaded cape (PNG bytes, already 256x128) and returns its id. */
function saveCustom (settings, png) {
  fs.mkdirSync(CUSTOM_DIR, { recursive: true })
  const id = 'custom_' + require('crypto').createHash('sha256').update(png).digest('hex').slice(0, 10)
  for (const f of fs.readdirSync(CUSTOM_DIR)) if (f !== id + '.png') fs.rmSync(path.join(CUSTOM_DIR, f), { force: true })
  fs.writeFileSync(customFile(id), png)
  settings.customCape = id
  return id
}

function removeCustom (settings) {
  if (settings.customCape) fs.rmSync(customFile(settings.customCape), { force: true })
  settings.customCape = ''
}

const customDataUrl = settings => 'data:image/png;base64,' + fs.readFileSync(customFile(settings.customCape)).toString('base64')

/** Copies the cape set next to the game when it changed; returns the folder. */
function install (root, settings = {}) {
  const dst = path.join(root, 'cosmetics', 'capes')
  const own = custom(settings)
  const want = own ? JSON.stringify(all(settings)) : fs.readFileSync(path.join(SRC, 'capes.json'), 'utf8')
  let have = ''
  try { have = fs.readFileSync(path.join(dst, 'capes.json'), 'utf8') } catch {}
  if (have !== want || !fs.existsSync(path.join(dst, firstFile()))) {
    fs.mkdirSync(dst, { recursive: true })
    for (const f of fs.readdirSync(SRC)) fs.copyFileSync(path.join(SRC, f), path.join(dst, f))
    for (const f of fs.readdirSync(dst)) if (f.startsWith('custom_')) fs.rmSync(path.join(dst, f), { force: true })
    if (own) {
      fs.copyFileSync(customFile(own.id), path.join(dst, own.id + '.png'))
      fs.writeFileSync(path.join(dst, 'capes.json'), want)
    }
  }
  return dst
}

function firstFile () {
  const c = catalog()[0]
  return c ? (c.frames > 1 ? `${c.id}_0.png` : `${c.id}.png`) : 'capes.json'
}

/** Fields for xion-launcher.json. A Xion+ cape is dropped without Xion+ (the game checks too). */
function handoff (root, settings, premium) {
  const c = byId(settings.cape, settings)
  return {
    capesDir: install(root, settings),
    cape: c && (c.tier === 'free' || premium) ? c.id : '',
    capeRev: settings.capeRev || 0
  }
}

module.exports = { catalog, all, byId, custom, saveCustom, removeCustom, customDataUrl, install, handoff }
